 {savedPlaces::FileLock held(file);check((bool)held,"lock can be held");auto busy=savedPlaces::update(file,{savedPlaces::Operation::Remove,beijing,L""});check(busy.status==savedPlaces::Status::Busy&&!busy.snapshot,"busy writer does not mutate local snapshots");}
 check(savedPlaces::update(file,{savedPlaces::Operation::Remove,beijing,L""}).status==savedPlaces::Status::Changed,"closing the lock handle releases it");
 std::vector<savedPlaces::Place> full;for(int i=0;i<64;++i)full.push_back({L"Place "+std::to_wstring(i),i-32.,i*2.,1});ensure(savedPlaces::write(file,full),"full fixture");check(savedPlaces::update(file,{savedPlaces::Operation::Add,beijing,L""}).status==savedPlaces::Status::Full,"collection limit remains enforced");
 {std::ofstream out(std::filesystem::path(file),std::ios::binary);out<<"corrupted";}check(savedPlaces::update(file,{savedPlaces::Operation::Add,beijing,L""}).status==savedPlaces::Status::Unreadable,"corrupt file blocks writes");std::ifstream bad(std::filesystem::path(file),std::ios::binary);std::string original((std::istreambuf_iterator<char>(bad)),{});bad.close();check(original=="corrupted","bad original is not overwritten");
 ensure(savedPlaces::write(file,{}),"concurrency fixture");std::wstring eventName=L"Local\\WorldMapSavedChecks-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64());HANDLE event=CreateEventW(nullptr,TRUE,FALSE,eventName.c_str());ensure(event!=nullptr,"event");wchar_t executable[MAX_PATH]{};GetModuleFileNameW(nullptr,executable,MAX_PATH);std::vector<PROCESS_INFORMATION> workers;
 for(int i=0;i<8;++i){std::wstring command=L"\""+std::wstring(executable)+L"\" --worker \""+file+L"\" \""+eventName+L"\" "+std::to_wstring(i)+L" 6";STARTUPINFOW si{sizeof(si)};PROCESS_INFORMATION pi{};ensure(CreateProcessW(nullptr,&command[0],nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&si,&pi),"worker launch");workers.push_back(pi);}SetEvent(event);
 bool allFinished=true,allCommitted=true;for(auto& pi:workers){allFinished=WaitForSingleObject(pi.hProcess,15000)==WAIT_OBJECT_0&&allFinished;DWORD code;GetExitCodeProcess(pi.hProcess,&code);allCommitted=code==0&&allCommitted;CloseHandle(pi.hThread);CloseHandle(pi.hProcess);}check(allFinished,"concurrent writers finish");check(allCommitted,"concurrent writers commit all requested additions");CloseHandle(event);
 std::vector<savedPlaces::Place> merged;check(savedPlaces::read(file,merged)&&merged.size()==48,"eight processes retain all 48 independent additions");for(int worker=0;worker<8;++worker)for(int i=0;i<6;++i)check(savedPlaces::find(merged,worker*4.+i*.1,worker*10.+i*.1)>=0,"every process contribution survives");std::cout<<checks<<" saved-store checks passed\n";return 0;
